mapper.delete:
DELETE FROM tb_terminal_network_outage_log
WHERE terminal_id = #{terminalId}
  AND id NOT IN (
    SELECT id
    FROM (
        SELECT id
        FROM tb_terminal_network_outage_log
        WHERE terminal_id = #{terminalId}
        ORDER BY occurred_at_iso DESC, id DESC
        LIMIT #{retainCount}
    ) retained
)

mapper.select:
SELECT id, terminal_id, event_hash, occurred_at_iso, failure_reason, retry_count, failure_started_at, failure_started_at_iso, recovered_at, recovered_at_iso, duration_sec, router_wan_ip, public_ip, outbound_ok, raw_json, created_at FROM tb_terminal_network_event WHERE terminal_id IN
#{terminalId}
ORDER BY terminal_id ASC, created_at DESC, id DESC
